 function box(value,label,minimum=strictNeuralFragments?1:8){if(!Array.isArray(value)||value.length!==4||!value.every(Number.isSafeInteger)||value[2]<=value[0]||value[3]<=value[1])throw fail('Invalid native '+label+' bounds.');const local=value.map((v,i)=>v-shift[i%2]),result=[Math.max(0,local[0]),Math.max(0,local[1]),Math.min(domain.width,local[2]),Math.min(domain.height,local[3])];if(result[2]-result[0]<minimum||result[3]-result[1]<minimum)throw new EngineError('SOURCE_SCOPE_EMPTY','An explicitly selected '+label+' has no qualified native rectangle inside the original-source crop.',{details:{label,minimum,originalBounds:[...value],localizedBounds:result}});if(local.some((v,i)=>v!==result[i]))intersections.push({label,input:local,intersection:result});return result;}
