 out.sourceRegionLocalization={...(meta??existing),schema,coordinates:'source-region-native',domainFingerprint:domain.fingerprint,originalSha256:domain.sourceSha256,originalGrid:[domain.sourceWidth,domain.sourceHeight],origin:[...domain.origin],width:domain.width,height:domain.height,...(strictNeuralFragments?{strictNativeFragments:true}:{}),policy:strictNeuralFragments?'Exact native fragment geometry with one-pixel minima; requires the qualified upstream strict adapter, with no model-grid reduction.':nativeRegions?'Exact native-grid declared acquisition jobs; a derived bounding frame is geometry, never an extra analysis. Candidate membership intersects every immutable source ceiling; only a declared encompassing acquisition may add context. No explicit source exclusion is admitted.':'Exact native-grid translation; neural half-open rectangles intersect the immutable source crop; empty or sub-minimum rectangles are refused; no encoded crop.',intersections:already?existing.intersections??[]:intersections};checkAbort(signal);return out;
